{
  "sql": "SELECT i.snapshot_date AS snapshot_date, p.product_id AS product_id, p.product_name AS product_name, i.stock_on_hand AS stock_on_hand FROM commerce.inventory AS i JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date = $1 ORDER BY 4 DESC, 2 ASC LIMIT 20",
  "parameters": [
    "2022-12-31"
  ],
  "explanation": "Retrieves the 20 products with the highest stock_on_hand for the specific snapshot date 2022-12-31. Joins inventory with products to get product names. Orders by stock_on_hand descending and product_id ascending for deterministic tie-breaking. Limits results to 20 rows."
}

{
  "sql": "SELECT i.snapshot_date AS snapshot_date, p.category AS category, SUM(i.stock_on_hand) AS stock_on_hand FROM commerce.inventory AS i JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date = $1 GROUP BY i.snapshot_date, p.category ORDER BY 3 DESC, 2 ASC LIMIT 200",
  "parameters": [
    "2022-12-31"
  ],
  "explanation": "Aggregates stock_on_hand by product category for the specific snapshot date 2022-12-31, joining inventory to products to access the category dimension."
}

