{
  "sql": "SELECT i.snapshot_date AS snapshot_date, p.category AS category, AVG(i.fill_rate) AS fill_rate FROM commerce.inventory AS i JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date >= $1 AND i.snapshot_date < $2 GROUP BY i.snapshot_date, p.category ORDER BY 1, 2 LIMIT 200",
  "parameters": [
    "2022-12-01",
    "2023-01-01"
  ],
  "explanation": "Calculates the mean stored fill rate by category for each snapshot date in December 2022. The query joins inventory with products to access the category dimension, filters for the specified month using date range parameters, and groups by snapshot date and category to compute the average fill rate for each group."
}

