{
  "sql": "SELECT p.product_id, p.product_name, SUM(oi.quantity) AS total_quantity FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 AND LOWER(o.order_status) NOT IN ('cancelled', 'canceled') GROUP BY p.product_id, p.product_name ORDER BY 3 DESC, p.product_id ASC LIMIT 20",
  "parameters": ["2022-01-01", "2023-01-01"],
  "explanation": "Joins order_items to orders and products to filter for non-cancelled orders in 2022. Sums the quantity per product, orders by total quantity descending with product_id as a tie-breaker, and limits the result to the top 20 products."
}

{
  "sql": "SELECT p.category, COUNT(DISTINCT o.order_id) AS order_count FROM commerce.orders AS o INNER JOIN commerce.order_items AS oi ON o.order_id = oi.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY p.category ORDER BY 1",
  "parameters": ["2022-12-01", "2023-01-01"],
  "explanation": "Counts distinct orders containing at least one item from each product category for December 2022."
}

{
  "sql": "SELECT p.category AS category, SUM(oi.quantity * oi.unit_price) AS gross_line_value FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY p.category ORDER BY 1 LIMIT 200",
  "parameters": ["2022-01-01", "2023-01-01"],
  "explanation": "Calculates the gross line value (quantity * unit_price) for each product category in 2022 by joining order items with orders and products, filtering by the specified date range, and aggregating by category."
}

{
  "sql": "SELECT p.category AS category, SUM(oi.quantity * oi.unit_price - oi.discount_amount) AS net_line_value FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY p.category ORDER BY 1 LIMIT 200",
  "parameters": [
    "2022-01-01",
    "2023-01-01"
  ],
  "explanation": "Calculates the net line value (quantity * unit_price - discount_amount) for each product category in 2022 by joining order_items with orders and products, filtering by order_date, and aggregating by category."
}

{
  "sql": "SELECT p.product_id, p.product_name, SUM(r.return_quantity) AS total_units_returned FROM commerce.products AS p INNER JOIN commerce.returns AS r ON p.product_id = r.product_id WHERE r.return_date >= $1 AND r.return_date < $2 GROUP BY p.product_id, p.product_name ORDER BY 3 DESC, p.product_id ASC LIMIT 10",
  "parameters": [
    "2022-01-01",
    "2023-01-01"
  ],
  "explanation": "Joins products and returns on product_id, filters returns for the year 2022, sums return_quantity per product, and selects the top 10 products by total units returned, using product_id as a tie-breaker."
}

{
  "sql": "SELECT p.category, SUM(r.refund_amount) AS total_refund_amount FROM commerce.returns AS r INNER JOIN commerce.products AS p ON r.product_id = p.product_id WHERE r.return_date >= $1 AND r.return_date < $2 GROUP BY p.category ORDER BY 1 LIMIT 200",
  "parameters": [
    "2022-01-01",
    "2023-01-01"
  ],
  "explanation": "Joins returns to products to access category, filters return dates to the year 2022, and sums the refund amounts grouped by category."
}

{
  "sql": "WITH returned_units AS (SELECT r.product_id, SUM(r.return_quantity) AS returned_units FROM commerce.returns AS r JOIN commerce.orders AS o ON r.order_id = o.order_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY r.product_id), ordered_units AS (SELECT oi.product_id, SUM(oi.quantity) AS ordered_units FROM commerce.order_items AS oi JOIN commerce.orders AS o ON oi.order_id = o.order_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY oi.product_id) SELECT p.product_id, p.product_name, ru.returned_units, ou.ordered_units, CAST(ru.returned_units AS NUMERIC) / NULLIF(ou.ordered_units, 0) AS return_ratio FROM returned_units AS ru INNER JOIN ordered_units AS ou ON ru.product_id = ou.product_id JOIN commerce.products AS p ON ru.product_id = p.product_id ORDER BY 5 DESC NULLS LAST, 1 ASC LIMIT 200",
  "parameters": [
    "2022-01-01",
    "2023-01-01"
  ],
  "explanation": "Calculates the ratio of returned units to ordered units for each product in 2022. It independently aggregates return quantities and order item quantities by product, joins them on product_id, and ranks by the ratio in descending order."
}

{
  "sql": "SELECT r.return_reason, SUM(r.return_quantity) AS total_returned FROM commerce.returns AS r WHERE r.return_date >= $1 AND r.return_date < $2 GROUP BY r.return_reason ORDER BY 1",
  "parameters": ["2022-01-01", "2023-01-01"],
  "explanation": "Aggregates return quantities by reason for returns occurring in 2022."
}

{
  "sql": "SELECT DISTINCT r.product_id, r.order_id FROM commerce.returns AS r INNER JOIN commerce.products AS p ON r.product_id = p.product_id INNER JOIN commerce.orders AS o ON r.order_id = o.order_id WHERE NOT EXISTS (SELECT 1 FROM commerce.order_items AS oi WHERE oi.product_id = p.product_id AND oi.order_id = o.order_id) ORDER BY 1, 2 LIMIT 200",
  "parameters": [],
  "explanation": "Identifies product-order pairs present in the returns table but missing from the order_items table by joining returns to products and orders, then using a NOT EXISTS clause to filter out pairs that have a corresponding record in order_items."
}

{
  "sql": "WITH inv_agg AS (SELECT p.category AS category, SUM(i.units_sold) AS inventory_units_sold FROM commerce.inventory AS i INNER JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date >= $1 AND i.snapshot_date < $2 GROUP BY p.category), ord_agg AS (SELECT p.category AS category, SUM(oi.quantity) AS ordered_quantity FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $3 AND o.order_date < $4 GROUP BY p.category) SELECT COALESCE(inv_agg.category, ord_agg.category) AS category, inv_agg.inventory_units_sold, ord_agg.ordered_quantity FROM inv_agg FULL JOIN ord_agg ON inv_agg.category = ord_agg.category ORDER BY 1",
  "parameters": ["2022-12-01", "2023-01-01", "2022-12-01", "2023-01-01"],
  "explanation": "Aggregates inventory units_sold and ordered quantities independently for December 2022 by category, then joins them to compare the metrics."
}

{
  "sql": "WITH grouped AS (SELECT snapshot_date, product_id, COUNT(*) AS cnt FROM commerce.inventory AS inv GROUP BY snapshot_date, product_id HAVING COUNT(*) > 1) SELECT SUM(cnt - 1) AS duplicate_rows FROM grouped",
  "parameters": [],
  "explanation": "Counts the number of excess rows in commerce.inventory where the (snapshot_date, product_id) key appears more than once, by summing (count - 1) for each duplicate group."
}
